CREATE TABLE IF NOT EXISTS treasury_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, jurisdiction text NOT NULL DEFAULT 'Nigeria', bank_name text, account_name text, account_purpose text NOT NULL, currency text NOT NULL DEFAULT 'NGN', mandate_status text NOT NULL DEFAULT 'Needs Verification', signatory_count integer NOT NULL DEFAULT 0, dual_authorization boolean NOT NULL DEFAULT true, reconciliation_frequency text NOT NULL DEFAULT 'Monthly', evidence_reference text, status text NOT NULL DEFAULT 'Planned', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS financial_controls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, control_area text NOT NULL, control_name text NOT NULL, control_level text NOT NULL DEFAULT 'High', maker_role text, checker_role text, threshold_amount numeric, currency text DEFAULT 'NGN', dual_authorization boolean NOT NULL DEFAULT true, approval_route text, evidence_required text, frequency text, status text NOT NULL DEFAULT 'Active', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS treasury_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, transaction_type text NOT NULL, description text NOT NULL, amount numeric NOT NULL, currency text NOT NULL DEFAULT 'NGN', requested_by text, approved_by text, checker text, approval_status text NOT NULL DEFAULT 'Pending', execution_status text NOT NULL DEFAULT 'Not Executed', transaction_reference text, evidence_reference text, requested_at timestamptz NOT NULL DEFAULT now(), executed_at timestamptz, notes text);
CREATE TABLE IF NOT EXISTS financial_budgets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, fiscal_year integer NOT NULL, budget_name text NOT NULL, department text, budget_amount numeric NOT NULL, currency text NOT NULL DEFAULT 'NGN', approved_amount numeric, approval_status text NOT NULL DEFAULT 'Draft', approved_by text, approval_date date, evidence_reference text, status text NOT NULL DEFAULT 'Open', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reconciliation_controls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, account_id uuid REFERENCES treasury_accounts(id), reconciliation_period date NOT NULL, opening_balance numeric, closing_balance numeric, ledger_balance numeric, variance numeric, prepared_by text, reviewed_by text, review_status text NOT NULL DEFAULT 'Pending', evidence_reference text, reviewed_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO financial_controls(entity_name,control_area,control_name,control_level,maker_role,checker_role,dual_authorization,approval_route,evidence_required,frequency,status) SELECT 'OSANVAULT AFRICA LTD','Payments','Maker-checker payment control','Critical','Authorized finance maker','Independent finance checker',true,'Approved authority route before execution','Payment request, invoice/contract, approval, bank confirmation and audit trail','Per transaction','Active' WHERE NOT EXISTS (SELECT 1 FROM financial_controls WHERE control_name='Maker-checker payment control');
INSERT INTO financial_controls(entity_name,control_area,control_name,control_level,maker_role,checker_role,threshold_amount,currency,approval_route,evidence_required,frequency,status) SELECT 'OSANVAULT AFRICA LTD','Banking','Bank mandate control','Critical','Company Secretary / designated finance officer','Authorized directors','0','NGN','Board-approved mandate and dual authorization','Resolution, bank mandate, identity/KYC evidence','On change','Active' WHERE NOT EXISTS (SELECT 1 FROM financial_controls WHERE control_name='Bank mandate control');
INSERT INTO financial_controls(entity_name,control_area,control_name,control_level,maker_role,checker_role,approval_route,evidence_required,frequency,status,notes) SELECT 'OSANVAULT AFRICA LTD','Reconciliation','Bank reconciliation','High','Finance preparer','Finance reviewer / control owner','Independent review of bank statement against ledger','Bank statement, ledger, reconciliation and variance explanation','Monthly','Active','Frequency may be increased for higher-risk or high-volume accounts.' WHERE NOT EXISTS (SELECT 1 FROM financial_controls WHERE control_name='Bank reconciliation');
INSERT INTO financial_controls(entity_name,control_area,control_name,control_level,maker_role,checker_role,approval_route,evidence_required,frequency,status) SELECT 'OSANVAULT AFRICA LTD','Budget','Budget-to-actual control','High','Budget owner','Finance controller','Approved budget plus variance escalation','Approved budget, actuals, variance analysis and escalation record','Monthly','Active' WHERE NOT EXISTS (SELECT 1 FROM financial_controls WHERE control_name='Budget-to-actual control');
INSERT INTO financial_controls(entity_name,control_area,control_name,control_level,maker_role,checker_role,approval_route,evidence_required,frequency,status) SELECT 'OSANVAULT AFRICA LTD','Treasury','Liquidity and cash position review','High','Treasury / Finance','CFO or designated executive','Periodic treasury review and escalation','Cash position, commitments, forecast and approval record','Weekly / Monthly','Active' WHERE NOT EXISTS (SELECT 1 FROM financial_controls WHERE control_name='Liquidity and cash position review');